CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE customers(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),external_reference TEXT UNIQUE,email TEXT UNIQUE,phone TEXT UNIQUE,legal_name TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN('pending','active','suspended','closed')),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE accounts(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),customer_id UUID REFERENCES customers(id),account_number TEXT NOT NULL UNIQUE,account_type TEXT NOT NULL CHECK(account_type IN('customer_wallet','settlement','fee','suspense','clearing')),currency CHAR(3) NOT NULL CHECK(currency ~ '^[A-Z]{3}$'),status TEXT NOT NULL DEFAULT 'active' CHECK(status IN('active','frozen','closed')),created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX accounts_customer_idx ON accounts(customer_id,status);
CREATE TABLE transactions(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),idempotency_scope TEXT NOT NULL,idempotency_key TEXT NOT NULL,request_hash BYTEA NOT NULL,transaction_type TEXT NOT NULL CHECK(transaction_type IN('deposit','withdrawal','transfer','fee','reversal','adjustment')),status TEXT NOT NULL CHECK(status IN('pending','posted','failed','reversed')),currency CHAR(3) NOT NULL CHECK(currency ~ '^[A-Z]{3}$'),amount_minor BIGINT NOT NULL CHECK(amount_minor>0),reference TEXT NOT NULL,description TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),posted_at TIMESTAMPTZ,UNIQUE(idempotency_scope,idempotency_key));
CREATE INDEX transactions_created_idx ON transactions(created_at DESC,id);
CREATE TABLE journal_entries(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),transaction_id UUID NOT NULL REFERENCES transactions(id),account_id UUID NOT NULL REFERENCES accounts(id),currency CHAR(3) NOT NULL CHECK(currency ~ '^[A-Z]{3}$'),direction SMALLINT NOT NULL CHECK(direction IN(-1,1)),amount_minor BIGINT NOT NULL CHECK(amount_minor>0),line_number SMALLINT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(transaction_id,line_number));
CREATE INDEX journal_account_history_idx ON journal_entries(account_id,created_at DESC,id);
CREATE TABLE account_balances(account_id UUID PRIMARY KEY REFERENCES accounts(id),posted_minor BIGINT NOT NULL DEFAULT 0,pending_minor BIGINT NOT NULL DEFAULT 0,version BIGINT NOT NULL DEFAULT 0,updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE audit_events(id BIGSERIAL PRIMARY KEY,actor_type TEXT NOT NULL,actor_id TEXT,action TEXT NOT NULL,resource_type TEXT NOT NULL,resource_id TEXT NOT NULL,correlation_id TEXT,metadata JSONB NOT NULL DEFAULT '{}'::jsonb,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE outbox_events(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),aggregate_type TEXT NOT NULL,aggregate_id UUID NOT NULL,event_type TEXT NOT NULL,payload JSONB NOT NULL,occurred_at TIMESTAMPTZ NOT NULL DEFAULT now(),published_at TIMESTAMPTZ,attempts INTEGER NOT NULL DEFAULT 0);
CREATE INDEX outbox_unpublished_idx ON outbox_events(occurred_at) WHERE published_at IS NULL;
CREATE OR REPLACE FUNCTION reject_journal_mutation() RETURNS trigger AS $$ BEGIN RAISE EXCEPTION 'journal entries are immutable; use compensating transactions'; END; $$ LANGUAGE plpgsql;
CREATE TRIGGER journal_entries_immutable BEFORE UPDATE OR DELETE ON journal_entries FOR EACH ROW EXECUTE FUNCTION reject_journal_mutation();
